#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=10.0.0.0/8 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging --description=pre-spoofed
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=10.0.0.0/8 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging --description=pre-spoofed
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=4,udp:3544,41,47 --description=prefilter-default-block-tunnels
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=4,udp:3544,41,47 --description=prefilter-default-block-tunnels
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=4,udp:3544,41,47 --description=prefilter-default-block-tunnels
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=4,udp:3544,41,47 --description=prefilter-default-block-tunnels
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=10.30.0.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=Block OT outbound'
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=10.30.0.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=Block OT outbound'
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=10.10.0.200/29,10.10.0.208/28,10.10.0.224/28,10.10.0.240/29,10.10.0.248/31,10.10.0.250/32 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:80,tcp:443 --enable-logging '--description=Uncategorised web'
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=10.10.0.200/29,10.10.0.208/28,10.10.0.224/28,10.10.0.240/29,10.10.0.248/31,10.10.0.250/32 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:80,tcp:443 --enable-logging '--description=Uncategorised web'
run compute network-firewall-policies rules create 1100 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=Reset the rest from inside'
run compute network-firewall-policies rules create 1110 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=Reset the rest from inside'
run compute network-firewall-policies rules create 1120 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --enable-logging '--description=Reset the rest from inside'
run compute network-firewall-policies rules create 1130 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --enable-logging '--description=Reset the rest from inside'
run compute network-firewall-policies rules create 1140 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1150 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1160 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1170 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   pre-backup: the source of the rule is in zone inside, and a rule of Google Cloud names no zone: give the networks behind inside with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   pre-partner-gre: the source of the rule is in zone outside, and a rule of Google Cloud names no zone: give the networks behind outside with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   pre-partner-gre-reverse: the source of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network; the destination of the rule is in zone outside, and a rule of Google Cloud names no zone: give the networks behind outside with --zone-network
#   LAN web: the source of the rule is in zone inside, and a rule of Google Cloud names no zone: give the networks behind inside with --zone-network; the destination of the rule is in zone outside, and a rule of Google Cloud names no zone: give the networks behind outside with --zone-network
#   LAN DNS and NTP: the source of the rule is in zone inside, and a rule of Google Cloud names no zone: give the networks behind inside with --zone-network; the destination of the rule is in zone outside, and a rule of Google Cloud names no zone: give the networks behind outside with --zone-network
#   Updates: the source of the rule is in zone inside, dmz, and a rule of Google Cloud names no zone: give the networks behind inside, dmz with --zone-network; host name object updates: the rules are written with addresses
#   Inbound web: the source of the rule is in zone outside, and a rule of Google Cloud names no zone: give the networks behind outside with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   Inbound mail: the source of the rule is in zone outside, and a rule of Google Cloud names no zone: give the networks behind outside with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   Admin access: the source of the rule is in zone inside, and a rule of Google Cloud names no zone: give the networks behind inside with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   Helpdesk RDP: source user match CORP\helpdesk is not converted; the source of the rule is in zone inside, and a rule of Google Cloud names no zone: give the networks behind inside with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dm
#   Staff social media: not converted: an application condition
#   Partner service: the source of the rule is in zone outside, and a rule of Google Cloud names no zone: give the networks behind outside with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   Old FTP: the source of the rule is in zone inside, and a rule of Google Cloud names no zone: give the networks behind inside with --zone-network; the destination of the rule is in zone outside, and a rule of Google Cloud names no zone: give the networks behind outside with --zone-network
#   DNS answers to resolver: the source of the rule is in zone outside, and a rule of Google Cloud names no zone: give the networks behind outside with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   Branch IPv6: the source of the rule is in zone outside, and a rule of Google Cloud names no zone: give the networks behind outside with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   Ping out: the source of the rule is in zone inside, dmz, and a rule of Google Cloud names no zone: give the networks behind inside, dmz with --zone-network

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
